// Вход: {severity, title, text, data, kind, items:[{asset_id, key}]}.
// v1 — тестовый канал: сообщение фиксируется в журнале выполнения n8n.
return $input.all().map(item => ({
  json: {
    channel: 'test',
    delivered_at: new Date().toISOString(),
    severity: item.json.severity || 'info',
    title: item.json.title || 'Stocker',
    text: item.json.text || '',
    kind: item.json.kind || 'general',
    items: item.json.items || [],
    data: item.json.data || null,
  },
}));

return $input.all()
  .map(item => item.json)
  .filter(d => Array.isArray(d.items) && d.items.length > 0)
  .map(d => ({ json: { channel: d.channel, kind: d.kind, severity: d.severity, title: d.title.slice(0, 200), items: d.items.slice(0, 200) } }));
